// We require the input vector to be non‐empty.
// We ensure:
//   1) the returned index is in‐bounds,
//   2) that a[result] is a global minimum over all entries of `a`,
//   3) that among any equal minima, we return the first one.
//
// Note: Verus automatically names the return value `result`.
#[requires(a.len() > 0)]
#[ensures(result < a.len())]
#[ensures(forall |j: usize| j < a.len() ==> a[result] <= a[j])]
#[ensures(forall |j: usize| j < result ==> a[j] > a[result])]
fn nanargmin(a: Vec<i8>) -> usize {
    // Initialize with the first element (we know a.len() > 0):
    let mut min_index: usize = 0;
    let mut min_value: i8 = a[0];

    // We will scan from i = 1 up to a.len()-1.  The following invariant
    // states that at the start of each iteration (with the current i):
    //   * 1 <= i <= a.len()
    //   * min_index < i
    //   * min_value == a[min_index]
    //   * Among all k < i, a[min_index] is the minimum,
    //   * and if there are ties, min_index is the first such tie.
    //
    // When i = a.len(), the loop is done, and the invariant still
    // guarantees min_index < a.len() and the desired minimality/tie‐breaking.
    #[invariant(1 <= i && i <= a.len())]
    #[invariant(min_index < i)]
    #[invariant(min_value == a[min_index])]
    #[invariant(forall |k: usize| k < i ==> a[min_index] <= a[k])]
    #[invariant(forall |k: usize| k < min_index ==> a[k] > a[min_index])]
    for (i, &val) in a.iter().enumerate().skip(1) {
        if val < min_value {
            min_value = val;
            min_index = i;
        }
        // after the update, the invariant must still hold for this same i
        // (Verus will check it automatically)
    }

    // At this point, i == a.len(), so min_index < a.len() and the invariant
    // guarantees that a[min_index] is the first global minimum.
    min_index
}

